#!/bin/sh
# Prints the Homebrew formula for a release, from that release's SHA256SUMS.
#   scripts/homebrew-formula.sh 0.27.0 path/to/SHA256SUMS > Formula/vapx.rb
set -eu
version="$1"
sums="$2"
sha() { awk -v f="vapx-$1" '$2 == f { print $1 }' "$sums"; }
url="https://github.com/Hex29A/vapx/releases/download/v$version"
for t in aarch64-apple-darwin x86_64-apple-darwin aarch64-unknown-linux-musl x86_64-unknown-linux-musl; do
  [ -n "$(sha "$t")" ] || { echo "missing $t in $sums" >&2; exit 1; }
done
cat <<RB
# Generated by vapx CI (scripts/homebrew-formula.sh) on each release. Do not edit by hand.
class Vapx < Formula
  desc "Axis camera management CLI via VAPIX"
  homepage "https://vapx.29a.se"
  version "$version"
  license "MIT"

  on_macos do
    on_arm do
      url "$url/vapx-aarch64-apple-darwin"
      sha256 "$(sha aarch64-apple-darwin)"
    end
    on_intel do
      url "$url/vapx-x86_64-apple-darwin"
      sha256 "$(sha x86_64-apple-darwin)"
    end
  end

  on_linux do
    on_arm do
      url "$url/vapx-aarch64-unknown-linux-musl"
      sha256 "$(sha aarch64-unknown-linux-musl)"
    end
    on_intel do
      url "$url/vapx-x86_64-unknown-linux-musl"
      sha256 "$(sha x86_64-unknown-linux-musl)"
    end
  end

  def install
    bin.install Dir["vapx-*"].first => "vapx"
  end

  test do
    assert_match version.to_s, shell_output("#{bin}/vapx --version")
  end
end
RB
